import { HTMLAttributes } from "react";
import { cn } from "@/lib/utils";

interface CardProps extends HTMLAttributes<HTMLDivElement> {
  hoverLift?: boolean;
  glass?: boolean;
  softBg?: boolean;
}

export function Card({
  className,
  hoverLift = true,
  glass = false,
  softBg = false,
  children,
  ...props
}: CardProps) {
  return (
    <div
      className={cn(
        "card",
        hoverLift && "card--hoverable",
        glass && "card--glass",
        softBg && "card--soft-bg",
        className
      )}
      {...props}
    >
      {children}
    </div>
  );
}
