"use client";

import { useEffect, useState } from "react";
import { SparklesIcon } from "@/components/icons";
import { LOADING_MESSAGES } from "@/constants";
import { cn } from "@/lib/utils";

interface LoadingScreenProps {
  messages?: string[];
  compact?: boolean;
}

export function LoadingScreen({ messages = LOADING_MESSAGES, compact = false }: LoadingScreenProps) {
  const [index, setIndex] = useState(0);

  useEffect(() => {
    const id = setInterval(() => {
      setIndex((i) => (i + 1) % messages.length);
    }, 1400);
    return () => clearInterval(id);
  }, [messages.length]);

  return (
    <div className={cn("loading-screen", compact && "loading-screen--compact")}>
      <div className="loading-orb-wrap">
        <div className="loading-orb-glow" />
        <div className="loading-orb">
          <SparklesIcon size={24} />
        </div>
      </div>
      <p key={index} className="loading-message">
        {messages[index]}
      </p>
    </div>
  );
}
